def agent_action(sandbox, agent_body, step_count):
    if agent_body is None or not agent_body.active:
        return

    front_x = sandbox.get_vehicle_front_x() or agent_body.position.x
    target_x = 26.0

    # Check if we're close to the target
    if front_x >= target_x - 0.1:
        # Stop when close to target
        for body in sandbox.bodies:
            if body.active:
                sandbox.apply_force(body, 0, 0, step_count=step_count)
        return

    # Calculate forces based on position
    THRUST_F = 300.0  # Adjusted to prevent joint overload
    LIFT_F = 600.0   # Increased lift force for deep channel

    # Check if in deep channel (reduced buoyancy)
    in_danger_zone = (16.5 <= front_x <= 19.5)

    # Apply force to paddles with cooldown
    last_step = {}
    for body in sandbox.bodies:
        if body not in last_step:
            last_step[body] = -18

    for body in sandbox.bodies:
        if step_count >= last_step[body] + 18:
            # Calculate force magnitude based on velocity
            vx = body.linearVelocity.x
            if vx > 1.8:
                force_multiplier = 0.1
            elif vx > 1.0:
                force_multiplier = 0.4
            else:
                force_multiplier = 0.8  # Increased force multiplier for better propulsion

            # Apply thrust and lift as needed
            fx = THRUST_F * force_multiplier
            fy = 0.0
            if in_danger_zone:
                fy = LIFT_F

            # Apply force
            sandbox.apply_force(body, fx, fy, step_count=step_count)

            # Update last step for this body
            last_step[body] = step_count
